// New early and preschool activities. These are participation invitations,
// not tests of ability; an adult can stop any activity at the first stop cue.

const adaptationFocus = {
  expression: '描述或讲述',
  analysis: '比较和发现',
  design: '选择材料和改法',
  coding: '按顺序触发结果',
  organization: '安排先后顺序',
  interpersonal: '轮流和表达需要',
  music: '聆听、声音或节奏',
  movement: '安全动作和停下',
  nature: '观察和照护线索'
};

function adaptationsFor(age, directionId, row) {
  const focus = adaptationFocus[directionId];
  const material = row.materials[0];
  const firstStep = row.steps[0];
  const secondStep = row.steps[1];
  const thirdStep = row.steps[2];
  if (age === 'early') {
    return {
      start: `照护者先独自用${material}完成“${firstStep}”，熟悉一次后再邀请孩子旁观；只记录孩子自愿看、听、触或移开，孩子不参与也算完成。`,
      practice: `照护者熟悉后，用${material}按“${secondStep}”重复两轮，每轮只改变一个${focus}条件，顺着孩子的看、听、触或移开信号继续或停下。`,
      apply: `照护者把“${thirdStep}”带到另一个日常场景，先准备同一${material}和停止信号；记录孩子自愿靠近或观看，不追求复现结果。`
    };
  }
  return {
    start: `成人先用${material}示范“${firstStep}”，再给孩子两种安全选择；孩子决定开始、改法或停止，成人不替孩子完成。`,
    practice: `让孩子亲自操作${material}并选择一个${focus}变化，成人只在“${secondStep}”卡住时提示；一轮后依据孩子或听众的具体反馈改一个步骤。`,
    apply: `换一个真实场景或听众，用${material}完成“${thirdStep}”，让孩子说明或带领其中一步；保留可跳过、休息和重新开始的选择。`
  };
}

function makeTask(age, directionId, row) {
  const {
    slug, level, title, summary, minutes, materials, steps, deliverable,
    observe, transfer, reflection, focus
  } = row;
  const id = `expand_${age}_${directionId}_${slug}`;
  return {
    id,
    directionId,
    ageGroups: [age],
    level,
    title,
    summary,
    minutes,
    materials,
    steps,
    deliverable,
    observe,
    transfer,
    reflection,
    rubric: [
      `记录标准：${observe[0]}`,
      `过程标准：${focus || '活动过程'}有清楚步骤，并保留可停止或可调整的选择`,
      `迁移标准：${transfer}`
    ],
    adaptations: adaptationsFor(age, directionId, row)
  };
}

